printf 'import json\nimport sys\nimport urllib.request\n\nport = open('\''port.txt'\'').read().strip()\n\n\ndef ask(messages):\n    body = json.dumps({'\''messages'\'': messages}).encode()\n    return json.load(urllib.request.urlopen('\''http://127.0.0.1:%%s/chat'\'' %% port, body, timeout=5))\n\n\ndef count_lines(path):\n    return str(len(open(path).read().splitlines()))\n\n\ndef main(question):\n    messages = [{'\''role'\'': '\''user'\'', '\''content'\'': question}]\n    while True:\n        reply = ask(messages)\n        if reply['\''type'\''] == '\''text'\'':\n            print(reply['\''text'\''])\n            return\n        messages.append({'\''role'\'': '\''assistant'\'', '\''tool_call'\'': reply})\n        messages.append({'\''role'\'': '\''tool'\'', '\''id'\'': reply['\''id'\''], '\''content'\'': count_lines(reply['\''arguments'\'']['\''path'\''])})\n\n\nmain(sys.argv[1])\n' > agent.py
